const base=new Date(2026,8,14,8);const days=Array.from({length:14},(_,i)=>{let d=new Date(base);d.setDate(d.getDate()+i);return {iso:`2026-09-${String(d.getDate()).padStart(2,'0')}`,short:d.toLocaleDateString('fr-FR',{weekday:'short'}).replace('.',''),num:d.getDate(),long:d.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}),d}});
