const state={screen:'explore',coach:0,day:0,period:'all',hour:'',sport:'Tout',query:'',maxPrice:80,maxDist:10,format:'Tous',sort:'distance',city:'Paris 11e',map:false,mapCoach:0,comp:[],favorites:saved.favorites||[],bookings:saved.bookings||[],closed:saved.closed||[],prices:saved.prices||{},messages:saved.messages||{},reviews:saved.reviews||{},history:[],booking:null,bookingTab:'upcoming',coachDay:0};
function legacyPersist(){try{localStorage.setItem('partant-v1',JSON.stringify({favorites:state.favorites,bookings:state.bookings,closed:state.closed,prices:state.prices,messages:state.messages,reviews:state.reviews}))}catch(e){toast('Stockage indisponible : vos actions restent valides pour cette visite.')}}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const price=c=>c.id===0?(cfg.services.find(s=>s.active)?.price||0):(state.prices[c.id]||c.price);
const key=(id,day,time)=>`${id}|${day}|${time}`;
function legacyAllSlots(c,d){if(d%7===6)return [];return d%3===0?c.slots:d%3===1?[['09:00','12:00','18:00','19:00'],['09:00','12:00','19:00'],['07:30','18:30','19:30'],['10:00','18:00','19:00'],['08:00','17:30','19:00'],['12:30','18:00','20:00']][c.id]:[['10:00','16:00','18:30'],['09:00','11:00','18:30'],['08:30','17:00','19:00'],['10:00','16:00','18:00'],['11:00','17:00','19:30'],['09:30','16:00','18:30']][c.id]}
function legacyAvail(c,d,ignoreId){return allSlots(c,d).filter(t=>!state.closed.includes(key(c.id,d,t))&&!state.bookings.some(b=>b.id!==ignoreId&&b.status==='confirmed'&&b.coach===c.id&&b.day===d&&Math.abs(mins(b.time)-mins(t))<60))}
const mins=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);
function matchingSlots(c){return avail(c,state.day).filter(t=>(state.period!=='evening'||mins(t)>=1080)&&(!state.hour||t===state.hour))}
function results(){return coaches.filter(c=>(state.city.startsWith('Paris')||state.format==='Visio')&&(state.sport==='Tout'||[c.sport,...c.tags].includes(state.sport))&&[c.name,c.sport,...c.tags,c.area].join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(state.query.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''))&&price(c)<=state.maxPrice&&(state.format==='Visio'||c.dist<=state.maxDist)&&(state.format==='Tous'||c.formats.includes(state.format))&&matchingSlots(c).length).sort((a,b)=>state.sort==='price'?price(a)-price(b):state.sort==='rating'?parseFloat(b.rating.replace(',','.'))-parseFloat(a.rating.replace(',','.')):a.dist-b.dist)}
const view=document.getElementById('view');const modal=document.getElementById('modal');
function toast(t){let e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),3200)}
function nav(){document.getElementById('nav').innerHTML=[['explore','search','Explorer'],['favorites','heart','Favoris'],['bookings','calendar','Séances'],['account','user','Mon espace']].map(([a,i,t])=>`<button class="navitem ${state.screen===a?'active':''}" data-action="nav" data-id="${a}" ${state.screen===a?'aria-current="page"':''}>${ic(i)}${t}</button>`).join('')}
function card(c){let slots=matchingSlots(c);return `<article class="coach-card" aria-label="${c.name}"><div class="portrait photo p${c.id}"><button class="full" style="height:100%;position:absolute;inset:0" data-action="profile" data-id="${c.id}" aria-label="Voir le profil de ${c.name}"></button><button class="iconbtn fav" data-action="fav" data-id="${c.id}" aria-label="${state.favorites.includes(c.id)?'Retirer':'Ajouter'} ${c.name} ${state.favorites.includes(c.id)?'des':'aux'} favoris" aria-pressed="${state.favorites.includes(c.id)}">${state.favorites.includes(c.id)?'<span style="font-size:25px">♥</span>':ic('heart')}</button><span class="tag">${ic('shield','sm')} Profil vérifié</span></div><div class="card-info"><div class="row between"><button style="padding:0;text-align:left;min-height:44px" data-action="profile" data-id="${c.id}"><h3>${c.name}</h3></button><span class="review">★ ${c.rating} <span class="muted">(${c.reviews})</span></span></div><div class="row between"><p>${c.sport}</p><div><span class="price">${price(c)} €</span><span class="small muted"> / 1 h</span></div></div><p>${c.area} <span aria-hidden="true">·</span> ${c.dist.toString().replace('.',',')} km</p></div><div class="slots-label">${ic('clock','sm')} ${state.day===0?"Aujourd’hui":state.day===1?'Demain':days[state.day].short+' '+days[state.day].num}${state.hour?' · '+state.hour:''} <span class="muted">· Réservation immédiate</span></div><div class="slots">${slots.slice(0,3).map(t=>`<button class="slot" data-action="book" data-id="${c.id}" data-time="${t}" aria-label="Réserver ${c.name}, ${days[state.day].long} à ${t}">${t}</button>`).join('')}<button class="slot more" data-action="profile" data-id="${c.id}" aria-label="Toutes les disponibilités de ${c.name}">${ic('arrow','sm')}</button></div><div class="card-bottom"><span class="small muted">${c.formats.slice(0,2).join(' · ')} · Tout compris</span><button data-action="compare-add" data-id="${c.id}" aria-pressed="${state.comp.includes(c.id)}">${state.comp.includes(c.id)?'✓ Sélectionné':'+ Comparer'}</button></div></article>`}
function activeFilters(){let chips=[];if(state.maxPrice<80)chips.push(['budget','Jusqu’à '+state.maxPrice+' €']);if(state.maxDist<10)chips.push(['distance',state.maxDist+' km max.']);if(state.format!=='Tous')chips.push(['format',state.format]);if(!['Tout','Running','Pilates','Musculation','Boxe','Yoga'].includes(state.sport))chips.push(['sport',state.sport]);return chips.length?`<div class="scrollrow" style="padding:12px 24px 0">${chips.map(([id,t])=>`<button class="chip" data-action="clear-filter" data-id="${id}" aria-label="Retirer le filtre ${t}">${t} ×</button>`).join('')}</div>`:''}
function explore(){let list=results();return `<header class="top"><div class="row between"><div class="wordmark">partant</div><button class="row place" data-action="location">${ic('pin','sm')}${esc(state.city)} ${ic('down','sm')}</button></div><h1>On bouge quand ?</h1><p class="sub">Trouvez votre coach. Réservez votre moment.</p><div class="scrollrow"><button class="chip ${state.day===0&&state.period==='all'&&!state.hour?'active':''}" data-action="time" data-id="today">Aujourd’hui</button><button class="chip ${state.day===0&&state.period==='evening'?'active':''}" data-action="time" data-id="evening">Ce soir</button><button class="chip ${state.day===1&&!state.hour?'active':''}" data-action="time" data-id="tomorrow">Demain</button><button class="chip ${state.hour||state.day>1?'active':''}" data-action="date">${ic('calendar','sm')} ${state.hour||state.day>1?days[state.day].short+' '+days[state.day].num+(state.hour?' · '+state.hour:''):'Date & heure'}</button></div></header><div class="sheet"><div class="scrollrow sports">${[['Tout','all'],['Running','run'],['Pilates','pilates'],['Musculation','strength'],['Boxe','boxing'],['Yoga','pilates'],['Autres','plus']].map(([s,i])=>`<button class="sport ${state.sport===s?'active':''}" data-action="sport" data-id="${s}">${ic(i)}${s}</button>`).join('')}</div><form class="searchbar" id="search-form">${ic('search','sm')}<input id="search" aria-label="Rechercher un sport, un coach ou un quartier" placeholder="Un sport, un coach, un quartier" value="${esc(state.query)}"><button class="iconbtn" type="button" data-action="filters" aria-label="Filtres">${ic('filter')}</button></form>${activeFilters()}<div class="results-head row between"><div><h2>${state.period==='evening'?'Votre séance de ce soir':'Des coachs, tout près.'}</h2><p><span class="result-count">${list.length}</span> disponibles · ${days[state.day].short} ${days[state.day].num} sept.${state.hour?' à '+state.hour:''}</p></div><div class="row"><button class="textbtn" data-action="sort">Trier</button><button class="iconbtn soft" data-action="map" aria-label="${state.map?'Voir la liste':'Voir la carte'}">${ic(state.map?'all':'map','sm')}</button></div></div>${state.comp.length?`<div class="compare-bar row between"><span class="small">${state.comp.length}/2 coachs sélectionnés</span><button data-action="compare" ${state.comp.length<2?'disabled':''}>Comparer →</button></div>`:''}${state.map?mapView(list):list.length?list.map(card).join(''):`<div class="empty">${ic('search')}<h2>Aucun coach sur ce créneau</h2><p>Essayez une autre heure, un budget plus large ou une séance en visio.</p><button class="pill" data-action="reset-filters">Élargir ma recherche</button><button class="textbtn" data-action="date">Choisir une autre date</button></div>`}<div class="app-footer">Des coachs indépendants. Du temps pour vous.<br><br>Démo · profils et créneaux fictifs</div></div>`}
function go(screen){if(state.screen!==screen)state.history.push({screen:state.screen,coach:state.coach});state.screen=screen;render();view.scrollTop=0;view.focus({preventScroll:true})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;act(b.dataset.action,b.dataset)});
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();state.query=document.getElementById('search').value;render()}});
function showModal(title,html){document.getElementById('modal-content').innerHTML=`<header class="dialog-head"><h2 id="modal-title">${title}</h2><button class="iconbtn" data-action="close" aria-label="Fermer">${ic('close')}</button></header><div class="dialog-body">${html}</div>`;if(!modal.open)modal.showModal()}
function closeModal(){modal.close()}
