function empty(title,copy,action='nav',id='explore',label='Explorer les coachs'){return `<div class="empty">${ic('calendar')}<h2>${title}</h2><p>${copy}</p><button class="pill" data-action="${action}" data-id="${id}">${label}</button></div>`}
function dayLabel(d){if(days[d])return days[d].long;let date=new Date(base);date.setDate(date.getDate()+d);return date.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}
function dateStrip(selected,action){return `<div class="scrollrow" aria-label="Choisir un jour">${days.map((d,i)=>`<button class="datebtn ${i===selected?'active':''}" data-action="${action}" data-id="${i}" aria-label="${d.long}" aria-pressed="${i===selected}"><span>${d.short}</span><b>${d.num}</b></button>`).join('')}</div>`}
function profile(){let c=coaches[state.coach],pd=state.profileDay??state.day;let slots=avail(c,pd);return `${pagebar('Votre coach',`<button class="iconbtn" data-action="fav" data-id="${c.id}" aria-label="${state.favorites.includes(c.id)?'Retirer des':'Ajouter aux'} favoris">${state.favorites.includes(c.id)?'♥':ic('heart')}</button>`)}<div class="detail-photo photo p${c.id}" role="img" aria-label="Portrait de ${c.name}"></div><div class="profile-sheet section"><div class="row between"><span class="badge">${ic('shield','sm')} Profil vérifié</span><span class="review">★ ${c.rating} · <button class="textbtn" data-action="profile-reviews">${c.reviews} avis</button></span></div><h1 style="margin:16px 0 6px">${c.name}</h1><p class="muted">${c.sport} · ${c.area}</p><h2 style="margin:22px 0 12px;font-size:22px">« ${c.quote} »</h2><div class="row wrap">${c.tags.map(t=>`<span class="badge">${t}</span>`).join('')}</div><div class="stats"><div><b>${c.years} ans</b><small>d’expérience</small></div><div><b>${c.sessions}</b><small>séances réalisées</small></div><div><b>${price(c)} €</b><small>les 60 minutes</small></div></div><div class="note row">${ic('check')}<span>Tous niveaux bienvenus.<br>Première séance adaptée à votre objectif.</span></div><div class="schedule" id="profile-schedule"><div class="row between subhead"><h2>Votre prochain moment</h2><small class="muted">Septembre 2026</small></div>${dateStrip(pd,'profile-day')}<p class="small muted" style="margin:16px 0 10px">${dayLabel(pd)} · 60 min · Heure de Paris</p><div class="slots">${slots.length?slots.map(t=>`<button class="slot" data-action="book" data-id="${c.id}" data-day="${pd}" data-time="${t}">${t}</button>`).join(''):'<p class="muted">Pas de créneau ce jour. Choisissez une autre date.</p>'}</div></div><div class="sep"></div><h2 class="subhead">Faire connaissance</h2><p>${c.bio}</p><h3 style="margin:22px 0 10px">Une séance avec ${c.name.split(' ')[0]}</h3><p class="muted">${c.method}</p><div class="sep"></div><h2 class="subhead">Où on se retrouve</h2><div class="row">${ic('pin')}<div><strong>${c.place}</strong><p class="small muted">${c.address}</p></div></div><p class="small muted" style="margin-top:14px">${c.formats.includes('Domicile')?'Se déplace à domicile dans un rayon de 3 km autour de son lieu de séance. Déplacement inclus. ':''}${c.formats.includes('Visio')?'Séances en visio également disponibles.':''}</p><div class="row wrap space">${c.formats.map(f=>`<span class="chip">${f}</span>`).join('')}</div><div class="sep"></div><h2 class="subhead">Entre de bonnes mains</h2><div class="stack"><div class="row">${ic('shield')}<div><strong>Identité et justificatifs vérifiés</strong><p class="small muted">${c.cert}</p></div></div><div class="row">${ic('message')}<span>${c.langs}</span></div></div><button class="textbtn space" data-action="trust">Comprendre la vérification</button><div class="sep"></div><div id="profile-reviews"><h2 class="subhead">★ ${c.rating} · ${c.reviews} avis</h2><div class="row between"><strong>${['Julie','Manon','Antoine','Élise','Hugo','Léa'][c.id]}</strong><small class="muted">Séance vérifiée · sept. 2026</small></div><p style="margin:12px 0">${['Une première séance sans appréhension. Thomas explique chaque mouvement et ajuste vraiment à mon niveau. Je repars motivée.','Sarah prend le temps de corriger les postures. Une heure précise et douce à la fois, je reviens la semaine prochaine.','Idriss a trouvé le rythme qui me convient. Pour la première fois, je me projette sur un 10 km.','Camille propose des variantes pour chaque posture. Je me suis sentie à l’aise dès le début.','Des explications claires, de la technique, et une progression que je comprends enfin.','Je n’avais jamais enfilé de gants. Inès met en confiance et la séance passe très vite.'][c.id]}</p><span class="small muted">Avis et vérifications simulés pour ce prototype.</span></div><div class="sep"></div><h3>Un imprévu ?</h3><p class="small muted" style="margin-top:8px">Annulation gratuite jusqu’à 24 h avant. Au-delà, la séance reste due. Modification gratuite jusqu’à 2 h avant, selon les disponibilités.</p><button class="textbtn space" data-action="report" data-id="${c.id}">Signaler ce profil</button></div><div class="sticky-cta"><div><strong style="font-size:22px">${price(c)} €</strong><p class="small muted">60 min · tout compris</p></div><button class="pill" data-action="profile-calendar">Voir les créneaux ${ic('arrow','sm')}</button></div>`}
function legacyLocationFor(b){let c=coaches[b.coach];if(b.format==='Visio')return {name:'En visioconférence',address:'Lien disponible dans le détail de votre séance'};if(b.format==='Domicile')return {name:'À votre domicile',address:b.home||'Adresse à préciser'};if(b.format===c.formats[0])return {name:c.place,address:c.address};if(b.format==='Parc')return {name:'Square Maurice-Gardette',address:'2 rue du Général-Blaise, 75011 Paris'};return {name:'Studio Voltaire',address:'22 rue de la Roquette, 75011 Paris'}}
function summaryPerson(b){let c=coaches[b.coach];return `<div class="summary-person"><div class="photo p${c.id} avatar" role="img" aria-label="${c.name}"></div><div><h3>${c.name}</h3><p>${c.sport} · ★ ${c.rating}</p></div></div>`}
function legacyStartBooking(id,time,day){const c=coaches[id];state.booking={coach:id,day:day??state.day,time,kind:'Individuel',format:state.format!=='Tous'&&c.formats.includes(state.format)?state.format:c.formats[0],home:'',payment:'apple'};state.editId=null;go('setup')}
function legacyBookingPrice(b){return price(coaches[b.coach])+(b.kind==='Duo'?20:0)}
function legacySetup(){let b=state.booking,c=coaches[b.coach];return `${pagebar('Votre séance')}<div class="section"><div class="eyebrow muted">01 — LES DÉTAILS</div><h1 style="margin:12px 0 24px">Un moment pour vous.</h1>${summaryPerson(b)}<button class="setting-row" data-action="booking-date"><div class="row">${ic('calendar')}<div><strong>${dayLabel(b.day)}</strong><small>${b.time} – ${endTime(b.time,b.duration||60)} · 60 min</small></div></div>${ic('chevron')}</button><h2 class="space subhead">Comment on s’entraîne ?</h2>${['Individuel','Duo'].map(k=>`<button class="choice ${b.kind===k?'active':''}" data-action="kind" data-id="${k}"><span class="radio"></span><span class="grow"><strong>${k==='Individuel'?'Juste vous':'À deux'}</strong><small>${k==='Individuel'?'Une séance entièrement personnalisée':'Venez avec la personne de votre choix'}</small></span><strong>${price(c)+(k==='Duo'?20:0)} €</strong></button>`).join('')}<h2 class="space subhead">Où on se retrouve ?</h2>${c.formats.map(f=>`<button class="choice ${b.format===f?'active':''}" data-action="format" data-id="${f}"><span class="radio"></span><span class="grow"><strong>${f==='Domicile'?'Chez vous':f==='Visio'?'En visio':f==='Parc'?'En extérieur':'Au studio'}</strong><small>${f==='Domicile'?'Dans un rayon de 3 km · déplacement inclus':f==='Visio'?'Le lien sera accessible après réservation':locationFor({...b,format:f}).name}</small></span></button>`).join('')}${b.format==='Domicile'?`<label class="field space">Adresse de la séance<input id="home-address" placeholder="Ex. 10 rue de la Roquette, Paris 11e" value="${esc(b.home)}"><small class="muted">Adresse fictive uniquement. Zone de déplacement simulée.</small></label>`:''}<div class="note space">${ic('shield','sm')} Annulation gratuite jusqu’à 24 h avant la séance.</div></div><div class="sticky-cta"><div><strong style="font-size:22px">${bookingPrice(b)} €</strong><p class="small muted">Prix total${b.kind==='Duo'?' pour deux':''}</p></div><button class="pill" data-action="checkout">Continuer ${ic('arrow','sm')}</button></div>`}
function legacyEndTime(t){let m=mins(t)+60;return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
function checkout(){let b=state.booking,l=locationFor(b);return `${pagebar('Récapitulatif')}<div class="section"><div class="eyebrow muted">02 — CONFIRMATION & PAIEMENT</div><h1 style="margin:12px 0 24px">Vous y êtes presque.</h1>${summaryPerson(b)}<div class="ticket"><div class="row">${ic('calendar')}<div><strong>${dayLabel(b.day)}</strong><p class="small">${b.time} – ${endTime(b.time,b.duration||60)} · 60 min · ${b.kind}</p></div></div><div class="sep"></div><div class="row">${ic('pin')}<div><strong>${l.name}</strong><p class="small muted">${esc(l.address)}</p></div></div></div><div class="receipt"><div class="row between"><span>Séance ${b.kind.toLowerCase()}</span><strong>${bookingPrice(b)} €</strong></div><div class="row between"><span>Frais de réservation</span><strong>0 €</strong></div><div class="row between total"><strong>Total à payer</strong><strong>${bookingPrice(b)} €</strong></div></div><h2 class="subhead">Votre moyen de paiement</h2>${[['apple','Apple Pay','Simulation en un geste'],['card','Carte bancaire','Carte de démonstration · •••• 4242']].map(([v,t,s])=>`<button class="choice ${b.payment===v?'active':''}" data-action="payment" data-id="${v}"><span class="radio"></span><span class="grow"><strong>${t}</strong><small>${s}</small></span>${ic('wallet')}</button>`).join('')}<div class="note space"><strong>Un changement de programme ?</strong><p style="margin-top:6px">${hoursUntil(b)<(b.cancelHours??24)?'Ce créneau commence dans moins de 24 h : une annulation ne donnera pas lieu à un remboursement.':'Annulez gratuitement jusqu’au '+cancellationDeadline(b)+'.'} Modification possible jusqu’à 2 h avant.</p></div><p class="small muted space">Mode démonstration : aucun débit, aucune donnée bancaire demandée. La réservation est enregistrée uniquement dans ce navigateur.</p></div><div class="sticky-cta"><button class="pill full" data-action="pay">${ic('shield','sm')} Réserver · ${bookingPrice(b)} €</button></div>`}
function hoursUntil(b){return b.day*24+(mins(b.time)-480)/60}
function legacyCancellationDeadline(b){let d=new Date(base);d.setDate(d.getDate()+b.day-1);return d.toLocaleDateString('fr-FR',{day:'numeric',month:'long'})+' à '+b.time}
function findBooking(){return state.bookings.find(b=>b.id===state.selectedBooking)||pastBooking}
const pastBooking={id:'past-sarah',coach:1,day:-3,time:'18:00',kind:'Individuel',format:'Studio',price:45,status:'completed'};
function confirmation(){let b=findBooking(),c=coaches[b.coach],l=locationFor(b);return `<div class="section" style="text-align:center"><div class="checkmark">${ic('check')}</div><div class="eyebrow muted">C’EST DANS L’AGENDA.</div><h1 style="margin:12px 0">Vous êtes partant.</h1><p class="muted">${c.name.split(' ')[0]} vous attend.<br>Votre séance est confirmée.</p><div class="ticket" style="text-align:left"><div class="eyebrow">${dayLabel(b.day)}</div><div class="when">${b.time} <span class="muted" style="font-size:20px;font-weight:400">– ${endTime(b.time,b.duration||60)}</span></div>${summaryPerson(b)}<div class="sep"></div><div class="row">${ic('pin')}<div><strong>${l.name}</strong><p class="small muted">${esc(l.address)}</p></div></div><div class="row between space small"><span>Réglé · ${b.kind}</span><strong>${b.price} €</strong></div></div><button class="pill full" data-action="booking-detail" data-id="${b.id}">Voir ma séance ${ic('arrow','sm')}</button><button class="pill light full" style="margin-top:10px" data-action="calendar-export" data-id="${b.id}">${ic('calendar','sm')} Ajouter au calendrier</button><button class="textbtn space" data-action="fav-confirm" data-id="${c.id}">${state.favorites.includes(c.id)?'♥ Coach dans vos favoris':'♡ Garder '+c.name.split(' ')[0]+' dans mes favoris'}</button><p class="small muted space">Confirmation simulée · aucun paiement effectué</p></div>`}
function bookingCard(b){let c=coaches[b.coach];return `<article class="booking-row"><div class="row between"><span class="eyebrow">${dayLabel(b.day)}</span><span class="badge">${b.status==='confirmed'?'Confirmée':b.status==='completed'?'Terminée':b.status==='no-show'?'Absence':'Annulée'}</span></div><div class="row between" style="margin-top:10px"><h2>${b.time} <span class="muted" style="font-weight:400;font-size:14px">· 60 min</span></h2><strong>${b.price} €</strong></div>${summaryPerson(b)}<button class="pill ${b.status==='confirmed'?'':'white'} full" data-action="${b.status==='confirmed'?'booking-detail':'rebook'}" data-id="${b.status==='confirmed'?b.id:c.id}">${b.status==='confirmed'?'Détails de la séance':'Réserver à nouveau'} ${ic('arrow','sm')}</button>${b.status==='completed'?`<button class="textbtn full" style="margin-top:8px" data-action="review" data-id="${b.id}">${state.reviews[b.id]?'Voir mon avis':'Laisser un avis'}</button>`:''}${b.status==='cancelled'?`<p class="small muted" style="margin-top:12px">Remboursement simulé : ${b.refund||0} €</p>`:''}</article>`}
function bookings(){let future=state.bookings.filter(b=>b.status==='confirmed').sort((a,b)=>a.day-b.day||mins(a.time)-mins(b.time)),history=[...state.bookings.filter(b=>b.status!=='confirmed'),pastBooking];return `<div class="section"><div class="row between"><span class="wordmark">partant</span>${ic('calendar')}</div><h1 style="margin:26px 0 8px">Vos rendez-vous<br>avec vous-même.</h1><p class="muted">On garde le rythme.</p><div class="row space"><button class="chip ${state.bookingTab==='upcoming'?'active':''}" data-action="booking-tab" data-id="upcoming">À venir · ${future.length}</button><button class="chip ${state.bookingTab==='past'?'active':''}" data-action="booking-tab" data-id="past">Passées · ${history.length}</button></div>${state.bookingTab==='upcoming'?(future.length?future.map(bookingCard).join(''):empty('Votre prochaine séance vous attend','Un footing, du Pilates, une heure pour vous. Trouvez le coach qui vous donne envie.')):history.map(bookingCard).join('')}</div>`}
function bookingDetail(){let b=findBooking(),c=coaches[b.coach],l=locationFor(b);return `${pagebar('Ma séance')}<div class="section"><span class="badge">${b.status==='confirmed'?'✓ Confirmée':b.status==='completed'?'Terminée':b.status==='no-show'?'Absence':'Annulée'} · ${esc(b.id.slice(-6).toUpperCase())}</span><h1 class="space">${dayLabel(b.day)}</h1><p style="font-size:26px;margin:8px 0 24px">${b.time} – ${endTime(b.time,b.duration||60)}</p>${summaryPerson(b)}<div class="sep"></div><h2 class="subhead">Le point de rendez-vous</h2><div class="row">${ic('pin')}<div><strong>${l.name}</strong><p class="small muted">${esc(l.address)}</p></div></div>${b.format==='Visio'?'<div class="note space">Le lien de visioconférence sera créé par le service dans la version réelle. Aucun appel n’est lancé dans cette démo.</div>':`<p class="small muted space">${b.format==='Domicile'?'Le coach vous retrouve à cette adresse.':'Retrouvez '+c.name.split(' ')[0]+' à l’entrée, 5 minutes avant la séance.'}</p>`}<div class="sep"></div><h2 class="subhead">Avant de venir</h2><p>Une tenue confortable, une bouteille d’eau et l’envie de bouger. ${c.id===5?'Les gants sont prêtés.':'Le petit matériel est fourni.'}</p><div class="receipt"><div class="row between"><span>${b.kind} · 60 min</span><strong>${b.price} €</strong></div><div class="row between"><span class="muted">Paiement</span><span>Simulé · ${b.status==='cancelled'?'annulé':'réglé'}</span></div></div>${b.status==='confirmed'?`<button class="pill full" data-action="message" data-id="${b.id}">${ic('message','sm')} Écrire à ${c.name.split(' ')[0]}</button><button class="setting-row" data-action="calendar-export" data-id="${b.id}"><span class="row">${ic('calendar')} Ajouter au calendrier</span>${ic('chevron')}</button><button class="setting-row" data-action="reschedule" data-id="${b.id}"><span>Modifier le créneau</span>${ic('chevron')}</button><button class="setting-row" data-action="cancel-booking" data-id="${b.id}"><span>Annuler la séance</span>${ic('chevron')}</button><p class="small muted space">Annulation gratuite jusqu’à 24 h avant ; au-delà, la séance reste due. Modification jusqu’à 2 h avant, selon disponibilité.</p>`:`<button class="pill full" data-action="rebook" data-id="${c.id}">Réserver à nouveau</button>`}<div class="note space"><strong>Et si on gardait le rythme ?</strong><p>Retrouvez tous les créneaux de ${c.name.split(' ')[0]} dans vos favoris. Vous réservez chaque séance à votre rythme.</p><button class="textbtn" data-action="fav-confirm" data-id="${c.id}">${state.favorites.includes(c.id)?'Retirer des favoris':'Ajouter aux favoris'}</button></div></div>`}
function favorites(){let list=coaches.filter(c=>state.favorites.includes(c.id));return `<div class="section"><span class="wordmark">partant</span><h1 style="margin:26px 0 8px">Les bons liens<br>se gardent.</h1><p class="muted">Vos coachs, leurs prochains créneaux.</p></div>${list.length?list.map(c=>{let d=days.findIndex((_,i)=>avail(c,i).length);return `<article class="coach-card"><div class="row"><div class="photo p${c.id} compact-photo"></div><div class="grow"><button class="textbtn" style="text-decoration:none" data-action="profile" data-id="${c.id}"><h3>${c.name}</h3></button><p class="small muted">${c.sport}</p><p class="small">★ ${c.rating} · ${price(c)} €/h</p></div><button class="iconbtn" data-action="fav" data-id="${c.id}" aria-label="Retirer ${c.name} des favoris">♥</button></div><div class="slots-label">${d>=0?dayLabel(d):'Aucun créneau ouvert'}</div><div class="slots">${d>=0?avail(c,d).slice(0,3).map(t=>`<button class="slot" data-action="book" data-id="${c.id}" data-day="${d}" data-time="${t}">${t}</button>`).join(''):''}</div></article>`}).join(''):empty('Votre équipe commence ici','Un coach vous plaît ? Touchez le cœur pour le retrouver ici, avec ses prochaines disponibilités.')}`}
function legacyAccount(){return `<div class="section"><span class="wordmark">partant</span><h1 style="margin:26px 0 22px">Bonjour, Alex.</h1><div class="row"><div class="iconbtn soft" style="width:60px;height:60px;font-size:22px;font-weight:800">A</div><div><strong>Alex Moreau</strong><p class="small muted">Profil de démonstration · Paris</p></div></div><div class="sep"></div><button class="setting-row" data-action="nav" data-id="bookings"><span class="row">${ic('calendar')} Mes séances</span>${ic('chevron')}</button><button class="setting-row" data-action="nav" data-id="favorites"><span class="row">${ic('heart')} Mes coachs favoris</span>${ic('chevron')}</button><button class="setting-row" data-action="location"><span class="row">${ic('pin')} Ma ville · ${esc(state.city)}</span>${ic('chevron')}</button><button class="setting-row" data-action="trust"><span class="row">${ic('shield')} Confiance & sécurité</span>${ic('chevron')}</button><button class="setting-row" data-action="help"><span class="row">${ic('message')} Une question ?</span>${ic('chevron')}</button><div class="note space"><h3>Vous faites bouger les autres ?</h3><p class="muted" style="margin:8px 0 16px">Ouvrez vos disponibilités. Vos prochains clients sont tout près.</p><button class="pill full" data-action="nav" data-id="coach">Découvrir l’espace coach ${ic('arrow','sm')}</button></div><details class="space"><summary class="small muted" style="cursor:pointer;min-height:44px">À propos de ce prototype</summary><p class="small muted">Démo figée au lundi 14 septembre 2026, à 08:00. Données sauvegardées dans ce navigateur. Carte schématique, vérifications, messages et paiements simulés.</p><button class="textbtn full" data-action="complete-demo">Simuler une séance terminée</button><button class="textbtn full" data-action="reset-demo">Réinitialiser la démo</button></details></div>`}
function mapView(list){if(!list.some(c=>c.id===state.mapCoach))state.mapCoach=list[0]?.id;let c=coaches[state.mapCoach];return `<div class="map" aria-label="Carte schématique de Paris"><svg viewBox="0 0 380 460" aria-hidden="true"><rect width="380" height="460" fill="#e9e9e9"/><g stroke="white" fill="none" stroke-width="12"><path d="M-20 75 400 340M10 -30 350 480M150 -20 140 500M275 -20 235 490M0 165l380 35M0 300l380-90M30 460 390 0M-20 390 400 330"/></g><path d="M-10 240C70 220 100 350 210 354S330 280 400 410" stroke="#c4c4c4" stroke-width="26" fill="none"/><g fill="#d4d4d4"><rect x="303" y="55" width="56" height="52" rx="18"/><rect x="36" y="325" width="47" height="65" rx="20"/></g><g font-family="Hanken,sans-serif" font-size="12" fill="#737373"><text x="124" y="230">LE MARAIS</text><text x="266" y="238">VOLTAIRE</text><text x="115" y="89">RÉPUBLIQUE</text><text x="197" y="400">BASTILLE</text><text x="32" y="283">LA SEINE</text><text x="245" y="51">BELLEVILLE</text><text x="50" y="140">PARIS</text></g><circle cx="233" cy="269" r="8" fill="#141414" stroke="white" stroke-width="4"/></svg>${list.map(c=>`<button class="pin ${state.mapCoach===c.id?'active':''}" style="left:${c.xy[0]}%;top:${c.xy[1]}%" data-action="map-select" data-id="${c.id}" aria-label="${c.name}, ${price(c)} euros">${price(c)} €</button>`).join('')}<span class="map-note">Carte schématique · positions indicatives</span></div>${c?`<div class="map-selection"><div class="row"><div class="photo p${c.id} compact-photo"></div><div class="grow"><button class="textbtn" style="text-decoration:none" data-action="profile" data-id="${c.id}"><h3>${c.name}</h3></button><p class="small muted">${c.sport} · ${c.dist} km</p><p class="small">★ ${c.rating} · ${price(c)} €/h</p></div></div><div class="slots-label">${dayLabel(state.day)} · ${c.formats.join(' / ')}</div><div class="slots">${matchingSlots(c).slice(0,3).map(t=>`<button class="slot" data-action="book" data-id="${c.id}" data-time="${t}">${t}</button>`).join('')}</div></div>`:''}`}
function coachScreen(){let c=coaches[0],d=state.coachDay,booked=state.bookings.filter(b=>b.coach===0&&b.status==='confirmed'),dayBooked=booked.filter(b=>b.day===d);return `${pagebar('Espace coach')}<header class="top" style="padding-bottom:36px"><div class="row between"><div><div class="eyebrow" style="color:#bbb">VOTRE TERRAIN DE JEU</div><h1 style="margin-top:12px">Bonjour, Thomas.</h1></div><div class="photo p0 avatar"></div></div><p class="sub">${booked.length} séance${booked.length>1?'s':''} à venir · Réservation automatique</p></header><div class="sheet section"><div class="row between subhead"><h2>Votre agenda</h2><small class="muted">Septembre</small></div>${dateStrip(d,'coach-day')}<div class="row between space"><strong>${dayLabel(d)}</strong><small class="muted">Heure de Paris</small></div><p class="small muted" style="margin:8px 0 20px">Touchez un créneau libre pour le fermer ou le rouvrir.</p>${allSlots(c,d).length?allSlots(c,d).map(t=>{let b=dayBooked.find(b=>Math.abs(mins(b.time)-mins(t))<60),closed=state.closed.includes(key(0,d,t));return `<div class="agenda-row"><time>${t}</time><button class="${b?'booked':closed?'closed':''}" data-action="${b?'coach-client':'coach-toggle'}" data-time="${t}" data-id="${b?b.id:''}"><strong>${b?'Alex Moreau':closed?'Indisponible':'Ouvert à la réservation'}</strong><p class="small">${b?b.kind+' · '+b.format+' · '+b.price+' €':closed?'Toucher pour ouvrir':'60 min · '+price(c)+' €'}</p></button></div>`}).join(''):'<div class="note">Journée de repos. Aucun créneau publié.</div>'}<div class="note space row">${ic('clock')}<span>Une réservation ferme immédiatement le créneau côté client. Aucune acceptation manuelle.</span></div><button class="setting-row" data-action="coach-offer"><span>Mon offre & mon tarif<small>Individuel ${price(c)} € · Duo ${price(c)+20} € · 60 min</small></span>${ic('chevron')}</button><button class="setting-row" data-action="coach-revenue"><span>Mes revenus<small>Commission de démonstration : 15 %</small></span>${ic('chevron')}</button><button class="setting-row" data-action="coach-sync"><span>Connecter un calendrier<small>Google, Apple, Outlook · aperçu</small></span>${ic('chevron')}</button><button class="setting-row" data-action="profile" data-id="0"><span>Voir mon profil public</span>${ic('chevron')}</button><button class="pill light full space" data-action="nav" data-id="explore">Revenir côté client ${ic('arrow','sm')}</button></div>`}
function legacyRender(){let pages={explore,favorites,bookings,account,profile,setup,checkout,confirmation,detail:bookingDetail,coach:coachScreen};view.innerHTML=`<div class="screen">${(pages[state.screen]||explore)()}</div>`;nav();document.getElementById('nav').classList.toggle('hidden',['setup','checkout','confirmation','coach'].includes(state.screen));}
function dateModal(mode='search',initial){let b=state.booking;let d=initial??(mode==='search'?state.day:mode==='reschedule'?state.rescheduleDay:b.day);state.modalDate=d;state.dateMode=mode;let c=coaches[mode==='reschedule'?findBooking().coach:b?.coach??0];let slots=mode==='search'?['','09:00','10:00','12:00','16:00','17:00','18:00','18:30','19:00','19:30','20:00']:avail(c,d,mode==='reschedule'?state.selectedBooking:undefined);showModal(mode==='search'?'Votre moment idéal':mode==='reschedule'?'Déplacer ma séance':'Choisir un créneau',`<p class="muted subhead">Septembre 2026 · Heure de Paris</p>${dateStrip(d,'modal-day')}<h3 class="space subhead">${dayLabel(d)}</h3>${mode==='search'?`<label class="field">À quelle heure ?<select id="desired-time">${slots.map(t=>`<option value="${t}" ${state.hour===t?'selected':''}>${t||'Toute la journée'}</option>`).join('')}</select></label><button class="pill full" data-action="apply-date">Voir les coachs disponibles</button>`:`<div class="slots">${slots.length?slots.map(t=>`<button class="slot" data-action="${mode==='reschedule'?'choose-reschedule':'choose-booking-time'}" data-time="${t}">${t}</button>`).join(''):'<p class="muted">Aucun créneau disponible. Essayez un autre jour.</p>'}</div>`}`)}
function filters(){showModal('Affiner votre recherche',`<form id="filters-form"><label class="field">Prix maximum par séance · <output id="price-value">${state.maxPrice} €</output><input type="range" min="30" max="80" step="5" value="${state.maxPrice}" name="budget" oninput="document.getElementById('price-value').textContent=this.value+' €'"></label><label class="field">Distance maximale<select name="distance">${[1,2,5,10].map(v=>`<option value="${v}" ${state.maxDist===v?'selected':''}>${v} km</option>`).join('')}</select></label><label class="field">Lieu de la séance<select name="format">${['Tous','Parc','Studio','Domicile','Visio'].map(v=>`<option ${state.format===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Discipline<select name="sport">${['Tout','Préparation physique','Running','Pilates','Musculation','Boxe','Yoga','Mobilité','Remise en forme','Perte de poids','Tennis','Football','Natation','Sports de combat','Récupération','Préparation compétition'].map(v=>`<option ${state.sport===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="small muted subhead">Prix pour 60 min en individuel, tout compris. La distance est indicative depuis ${esc(state.city)} ; elle ne s’applique pas en visio.</p><button class="pill full" type="submit">Afficher les résultats</button><button class="textbtn full" type="button" data-action="reset-filters">Réinitialiser les filtres</button></form>`)}
function legacyDoPay(){let b=state.booking;if(!avail(coaches[b.coach],b.day).includes(b.time)){showModal('Ce créneau n’est plus disponible',`<p class="muted subhead">Choisissez une autre heure avec votre coach.</p><button class="pill full" data-action="booking-date">Voir les disponibilités</button>`);return}if(state.bookings.some(x=>x.status==='confirmed'&&x.day===b.day&&Math.abs(mins(x.time)-mins(b.time))<60)){showModal('Vous avez déjà une séance',`<p class="muted subhead">Une réservation chevauche ce créneau. Choisissez une autre heure pour avoir le temps de profiter des deux séances.</p><button class="pill full" data-action="booking-date">Changer de créneau</button>`);return}let booked={...b,id:'pt-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),price:bookingPrice(b),status:'confirmed'};state.bookings.push(booked);state.selectedBooking=booked.id;persist();state.history=[];go('confirmation')}
function resetFilters(){Object.assign(state,{day:0,period:'all',hour:'',sport:'Tout',query:'',maxPrice:80,maxDist:10,format:'Tous',city:'Paris 11e'});closeModal();render()}
function openChat(id){state.selectedBooking=id;let b=findBooking(),c=coaches[b.coach],msgs=state.messages[id]||[];showModal(c.name.split(' ')[0],`<p class="small muted">Messagerie de démonstration · aucun envoi réel</p><div class="chat"><div class="bubble">Bonjour Alex ! Pensez à prendre une bouteille d’eau. On se retrouve ${dayLabel(b.day)} à ${b.time}. À très vite !</div>${msgs.map(t=>`<div class="bubble ${t.startsWith('[Coach] ')?'':'mine'}">${esc(t.replace(/^\[Coach\] /,''))}</div>`).join('')}</div><form id="message-form"><label class="field">Votre message<input id="message-text" maxlength="500" placeholder="Une question avant la séance ?" required autocomplete="off"></label><button class="pill full">Envoyer dans la démo ${ic('arrow','sm')}</button></form>`)}
function calendarExport(b){let start=new Date(base);start.setDate(start.getDate()+b.day);start.setHours(...b.time.split(':').map(Number),0,0);let end=new Date(start.getTime()+(b.duration||60)*60000);const stamp=d=>d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0')+'T'+String(d.getHours()).padStart(2,'0')+String(d.getMinutes()).padStart(2,'0')+'00';let c=coaches[b.coach],l=locationFor(b);const ce=t=>String(t).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let file=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Partant//Prototype//FR','BEGIN:VTIMEZONE','TZID:Europe/Paris','BEGIN:DAYLIGHT','DTSTART:20260329T020000','TZOFFSETFROM:+0100','TZOFFSETTO:+0200','TZNAME:CEST','END:DAYLIGHT','BEGIN:STANDARD','DTSTART:20261025T030000','TZOFFSETFROM:+0200','TZOFFSETTO:+0100','TZNAME:CET','END:STANDARD','END:VTIMEZONE','BEGIN:VEVENT','UID:'+b.id+'@partant.demo','DTSTAMP:20260914T060000Z','DTSTART;TZID=Europe/Paris:'+stamp(start),'DTEND;TZID=Europe/Paris:'+stamp(end),'SUMMARY:'+ce('Démo Partant · '+c.sport+' avec '+c.name),'LOCATION:'+ce(l.name+' - '+l.address),'DESCRIPTION:Réservation fictive issue du prototype Partant.','END:VEVENT','END:VCALENDAR'].join('\r\n');let url=URL.createObjectURL(new Blob([file],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='partant-seance.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Fichier calendrier téléchargé')}
function reviewModal(id){state.reviewId=id;let r=state.reviews[id];state.reviewRating=r?.rating||5;showModal(r?'Votre avis':'Comment était la séance ?',`<p class="muted">Votre retour aide les prochains sportifs.</p><div class="starbuttons">${[1,2,3,4,5].map(n=>`<button class="${n<=state.reviewRating?'active':''}" data-action="review-rating" data-id="${n}" aria-label="${n} étoile${n>1?'s':''}">★</button>`).join('')}</div><form id="review-form"><label class="field">Votre expérience<textarea id="review-text" placeholder="Qu’avez-vous apprécié ?" maxlength="1000" required>${esc(r?.text||'')}</textarea></label><button class="pill full">${r?'Mettre à jour':'Publier'} mon avis dans la démo</button><p class="small muted space">Avis stocké localement, lié à une séance terminée.</p></form>`)}
function legacyAct(a,d){switch(a){
case 'close':closeModal();break;
case 'back':{closeModal();let prev=state.history.pop();if(prev){state.screen=prev.screen;state.coach=prev.coach;render();view.scrollTop=0}else go('explore');break}
case 'nav':closeModal();go(d.id);break;
case 'scenario':closeModal();if(d.id==='time'){resetFilters();state.day=1;state.hour='19:00';state.screen='explore';render();view.scrollTop=0}else go(d.id);break;
case 'time':state.day=d.id==='tomorrow'?1:0;state.period=d.id==='evening'?'evening':'all';state.hour='';render();break;
case 'date':dateModal();break;
case 'modal-day':dateModal(state.dateMode,+d.id);break;
case 'apply-date':state.day=state.modalDate;state.hour=document.getElementById('desired-time').value;state.period='all';closeModal();render();break;
case 'sport':if(d.id==='Autres')filters();else{state.sport=d.id;render()}break;
case 'filters':filters();break;
case 'clear-filter':if(d.id==='budget')state.maxPrice=80;if(d.id==='distance')state.maxDist=10;if(d.id==='format')state.format='Tous';if(d.id==='sport')state.sport='Tout';render();break;
case 'reset-filters':resetFilters();break;
case 'sort':showModal('Trier les coachs',`<div class="stack">${[['distance','Les plus proches'],['price','Prix croissant'],['rating','Les mieux notés']].map(([v,t])=>`<button class="choice ${state.sort===v?'active':''}" data-action="apply-sort" data-id="${v}"><span class="radio"></span>${t}</button>`).join('')}</div>`);break;
case 'apply-sort':state.sort=d.id;closeModal();render();break;
case 'location':showModal('Où voulez-vous bouger ?',`<p class="muted subhead">Paris est la ville pilote de cette démo.</p><form id="location-form"><label class="field">Ville ou quartier<select id="city">${['Paris 11e','Paris','Lyon','Bordeaux','Marseille'].map(c=>`<option ${state.city===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="pill full">Explorer cette ville</button></form><p class="small muted space">Aucune géolocalisation requise. Pour les autres villes, découvrez l’état sans offre locale ou choisissez la visio.</p>`);break;
case 'map':state.map=!state.map;render();break;
case 'map-select':state.mapCoach=+d.id;render();break;
case 'fav':{let y=view.scrollTop,id=+d.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();render();view.scrollTop=y;break}
case 'fav-confirm':{let id=+d.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();render();toast(state.favorites.includes(id)?'Coach ajouté à vos favoris':'Coach retiré des favoris');break}
case 'compare-add':{let id=+d.id,y=view.scrollTop;if(state.comp.includes(id))state.comp=state.comp.filter(x=>x!==id);else if(state.comp.length<2)state.comp.push(id);else{toast('Comparez deux coachs à la fois. Retirez-en un pour changer.');return}render();view.scrollTop=y;break}
case 'compare':showModal('Votre duo de possibilités',`<p class="small muted subhead">${dayLabel(state.day)} · 60 min en individuel</p><div class="compare-grid">${state.comp.map(id=>{let c=coaches[id];return `<div class="compare-item"><div class="photo p${id}"></div><div><h3>${c.name}</h3><p class="small muted">${c.sport}</p></div><div><strong>${price(c)} €</strong> tout compris</div><div>★ ${c.rating} · ${c.reviews} avis</div><div>${c.dist} km<br><span class="small muted">${c.area}</span></div><div>${c.years} ans d’expérience</div><div>${c.formats.join(' · ')}</div><div>${matchingSlots(c).join(' · ')||'Plus de disponibilité'}</div><button class="pill full space" data-action="profile" data-id="${id}">Voir le profil</button></div>`}).join('')}</div>`);break;
case 'profile':closeModal();state.coach=+d.id;state.profileDay=state.day;go('profile');break;
case 'rebook':state.coach=+d.id;state.profileDay=days.findIndex((_,i)=>avail(coaches[+d.id],i).length);if(state.profileDay<0)state.profileDay=0;go('profile');break;
case 'profile-day':{let y=view.scrollTop;state.profileDay=+d.id;render();view.scrollTop=y;break}
case 'profile-calendar':document.getElementById('profile-schedule').scrollIntoView({behavior:'smooth',block:'start'});break;
case 'profile-reviews':document.getElementById('profile-reviews').scrollIntoView({behavior:'smooth',block:'start'});break;
case 'book':closeModal();startBooking(+d.id,d.time,d.day===undefined?state.day:+d.day);break;
case 'booking-date':dateModal('booking');break;
case 'choose-booking-time':state.booking.day=state.modalDate;state.booking.time=d.time;closeModal();render();break;
case 'kind':state.booking.kind=d.id;render();break;
case 'format':{if(document.getElementById('home-address'))state.booking.home=document.getElementById('home-address').value;state.booking.format=d.id;render();break}
case 'checkout':{if(state.booking.format==='Domicile'){let v=document.getElementById('home-address');if(!v.value.trim()){v.setCustomValidity('Indiquez une adresse fictive de rendez-vous.');v.reportValidity();return}state.booking.home=v.value.trim();v.setCustomValidity('')}go('checkout');break}
case 'payment':state.booking.payment=d.id;{let y=view.scrollTop;render();view.scrollTop=y}break;
case 'pay':doPay();break;
case 'booking-tab':state.bookingTab=d.id;render();break;
case 'booking-detail':state.selectedBooking=d.id;go('detail');break;
case 'calendar-export':calendarExport(state.bookings.find(b=>b.id===d.id)||findBooking());break;
case 'message':openChat(d.id);break;
case 'cancel-booking':{let b=findBooking();let refund=hoursUntil(b)>=(b.cancelHours??24)?b.price:0;showModal('Annuler cette séance ?',`<p>${dayLabel(b.day)} à ${b.time} avec ${coaches[b.coach].name}.</p><div class="note space"><strong>Remboursement simulé : ${refund} €</strong><p>${refund?'Votre annulation intervient plus de 24 h avant la séance.':'La séance commence dans moins de 24 h. Son montant reste dû.'}</p></div><button class="pill full space" data-action="confirm-cancel">Confirmer l’annulation</button><button class="pill light full" style="margin-top:10px" data-action="close">Garder ma séance</button>`);break}
case 'confirm-cancel':{let b=findBooking();b.status='cancelled';b.refund=hoursUntil(b)>=(b.cancelHours??24)?b.price:0;persist();closeModal();state.bookingTab='past';go('bookings');toast('Séance annulée. Le créneau est à nouveau disponible.');break}
case 'reschedule':{let b=findBooking();if(hoursUntil(b)<2){toast('La modification ferme 2 h avant le début de la séance.');break}state.rescheduleDay=b.day;dateModal('reschedule',b.day);break}
case 'choose-reschedule':{state.rescheduleChoice={day:state.modalDate,time:d.time};let b=findBooking();showModal('Confirmer ce nouveau moment',`<h3>${dayLabel(state.modalDate)} à ${d.time}</h3><p class="muted space">${coaches[b.coach].name} · ${b.kind} · ${b.format}</p><p class="note space">Même séance, même prix : ${b.price} €. Votre ancien créneau sera libéré.</p><button class="pill full space" data-action="confirm-reschedule">Confirmer la modification</button>`);break}
case 'confirm-reschedule':{let b=findBooking(),r=state.rescheduleChoice;if(!avail(coaches[b.coach],r.day,b.id).includes(r.time)){toast('Ce créneau n’est plus disponible.');dateModal('reschedule',r.day);break}if(state.bookings.some(x=>x.id!==b.id&&x.status==='confirmed'&&x.day===r.day&&Math.abs(mins(x.time)-mins(r.time))<60)){toast('Vous avez déjà une séance à cette heure.');dateModal('reschedule',r.day);break}Object.assign(b,r);persist();closeModal();render();toast('Séance déplacée. Pensez à actualiser votre calendrier.');break}
case 'review':reviewModal(d.id);break;
case 'review-rating':state.reviewRating=+d.id;document.querySelectorAll('.starbuttons button').forEach(b=>b.classList.toggle('active',+b.dataset.id<=state.reviewRating));break;
case 'coach-day':state.coachDay=+d.id;{let y=view.scrollTop;render();view.scrollTop=y}break;
case 'coach-toggle':{let k=key(0,state.coachDay,d.time),y=view.scrollTop;state.closed=state.closed.includes(k)?state.closed.filter(x=>x!==k):[...state.closed,k];persist();render();view.scrollTop=y;toast(state.closed.includes(k)?'Créneau fermé côté client':'Créneau disponible à la réservation');break}
case 'coach-client':state.selectedBooking=d.id;showModal('Votre prochaine séance',`${summaryPerson(findBooking())}<div class="note space"><strong>Client : Alex Moreau</strong><p>${dayLabel(findBooking().day)} · ${findBooking().time}<br>${findBooking().kind} · ${findBooking().format}</p></div><p class="small muted space">Réservation confirmée automatiquement. Le créneau ne peut plus être fermé comme une disponibilité libre.</p>`);break;
case 'coach-offer':showModal('Votre offre',`<form id="offer-form"><h3 class="subhead">Préparation physique · Thomas Martin</h3><label class="field">Tarif individuel · 60 min<input type="number" name="price" min="30" max="80" step="1" value="${price(coaches[0])}" required></label><p class="note">Le duo est proposé à votre tarif individuel + 20 €. Une modification de tarif ne change pas les réservations déjà payées.</p><p class="small muted space">Lieux : Square Maurice-Gardette, Studio Voltaire, domicile dans un rayon de 3 km. Déplacements inclus.</p><button class="pill full space">Enregistrer le tarif</button></form>`);break;
case 'coach-revenue':{let sales=state.bookings.filter(b=>b.coach===0&&(b.status!=='cancelled'||b.refund===0));let gross=sales.reduce((s,b)=>s+b.price,0);let euros=n=>n.toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';showModal('Vos revenus',`<p class="eyebrow muted">RÉSERVATIONS DE LA DÉMO</p><h1 class="space">${euros(gross*.85)}</h1><p class="muted">Revenu net prévisionnel</p><div class="receipt"><div class="row between"><span>Séances vendues</span><strong>${euros(gross)}</strong></div><div class="row between"><span>Commission Partant · 15 %</span><strong>− ${euros(gross*.15)}</strong></div><div class="row between total"><strong>Net coach</strong><strong>${euros(gross*.85)}</strong></div></div><p class="note">Hypothèse de modèle économique. Aucun versement réel. Dans le produit final, le versement interviendrait après la séance.</p>`);break}
case 'coach-sync':showModal('Vos agendas, au même endroit',`<p class="muted subhead">Aperçu de la future synchronisation.</p>${['Google Calendar','Apple Calendar','Outlook'].map(t=>`<div class="setting-row"><span>${t}</span><span class="badge">À venir</span></div>`).join('')}<p class="note space">Un événement occupé masquerait le créneau public. Une nouvelle réservation créerait un événement. Un délai de déplacement serait ajouté entre les lieux.</p><p class="small muted space">Aucune connexion externe dans ce prototype.</p>`);break;
case 'trust':showModal('La confiance, concrètement',`<div class="stack"><h3>Un coach, une identité.</h3><p>Le badge « Profil vérifié » représente le contrôle de l’identité et des justificatifs affichés sur le profil. Le périmètre dépend de la discipline.</p><h3>Des avis liés aux séances.</h3><p>Un avis se dépose après une séance terminée. Une note seule ne remplace pas les qualifications du coach.</p><h3>Des règles avant de réserver.</h3><p>Prix total, lieu et conditions d’annulation sont visibles avant confirmation. Un signalement reste accessible sur chaque profil.</p><div class="note">Démo : tous les profils, justificatifs, avis et contrôles sont fictifs. Le badge ne représente aucune vérification réelle.</div></div>`);break;
case 'report':showModal('Signaler ce profil',`<form id="report-form"><label class="field">Motif<select><option>Informations inexactes</option><option>Comportement inapproprié</option><option>Problème avec une certification</option><option>Autre</option></select></label><label class="field">Précisions<textarea required maxlength="1000" placeholder="Décrivez le problème avec ce profil fictif."></textarea></label><button class="pill full">Simuler le signalement</button><p class="small muted space">Aucun signalement n’est transmis à un service externe.</p></form>`);break;
case 'help':showModal('On vous accompagne',`<div class="stack"><h3>Comment réserver ?</h3><p>Choisissez un créneau sur une fiche coach, précisez le format puis confirmez. Aucun compte n’est nécessaire pour essayer la démo.</p><h3>Un imprévu ?</h3><p>Dans Séances, ouvrez le détail de votre réservation pour modifier, annuler ou écrire au coach.</p><h3>Et mes données ?</h3><p>Vos essais restent dans ce navigateur. Vous pouvez les effacer depuis « À propos de ce prototype ».</p></div>`);break;
case 'complete-demo':{let b=state.bookings.find(b=>b.status==='confirmed');if(!b){toast('Réservez d’abord une séance, puis simulez sa fin ici.');break}b.status='completed';persist();state.bookingTab='past';go('bookings');toast('Séance terminée dans la démo : vous pouvez laisser un avis.');break}
case 'reset-demo':showModal('Recommencer la démo ?',`<p>Les réservations, favoris, messages, avis et changements de planning de ce navigateur seront remis à zéro.</p><button class="pill full space" data-action="confirm-reset">Réinitialiser</button><button class="textbtn full" data-action="close">Conserver mes essais</button>`);break;
case 'confirm-reset':Object.assign(state,{favorites:[],bookings:[],closed:[],prices:{},messages:{},reviews:{},comp:[],history:[],map:false,screen:'explore'});persist();resetFilters();view.scrollTop=0;toast('La démo est prête pour un nouveau parcours.');break;
}}
document.addEventListener('submit',e=>{const id=e.target.id;if(!['filters-form','location-form','message-form','review-form','offer-form','report-form'].includes(id))return;e.preventDefault();if(id==='filters-form'){const f=new FormData(e.target);state.maxPrice=+f.get('budget');state.maxDist=+f.get('distance');state.format=f.get('format');state.sport=f.get('sport');closeModal();render()}if(id==='location-form'){state.city=document.getElementById('city').value;closeModal();go('explore');render()}if(id==='message-form'){let t=document.getElementById('message-text').value.trim();if(!t)return;(state.messages[state.selectedBooking]??=[]).push(t);persist();openChat(state.selectedBooking)}if(id==='review-form'){let text=document.getElementById('review-text').value.trim();if(!text)return;state.reviews[state.reviewId]={rating:state.reviewRating,text};persist();closeModal();render();toast('Merci ! Votre avis est enregistré dans cette démo.')}if(id==='offer-form'){state.prices[0]=+new FormData(e.target).get('price');persist();closeModal();render();toast('Tarif mis à jour sur votre profil public')}if(id==='report-form'){closeModal();toast('Signalement simulé. Aucun envoi réel.')}});
modal.addEventListener('click',e=>{if(e.target===modal){let r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
