 const registrations=[
 {name:'read_available_coaches',description:'Read the fictional coaches and time slots matching the current visible Partant filters. No booking is created.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({date:days[state.day].iso,coaches:results().map(c=>({id:c.id,name:c.name,price:price(c),slots:matchingSlots(c)}))})},
 {name:'start_demo_booking',description:'Open the session setup for a fictional coach and available slot. Does not confirm or pay for a booking.',inputSchema:{type:'object',properties:{coachId:{type:'integer',minimum:0,maximum:5},dayIndex:{type:'integer',minimum:0,maximum:13},time:{type:'string'}},required:['coachId','dayIndex','time'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.coachId)||!Number.isInteger(input.dayIndex)||!coaches[input.coachId]||!days[input.dayIndex]||!avail(coaches[input.coachId],input.dayIndex).includes(input.time))throw new Error('Coach, date or slot unavailable');closeModal();startBooking(input.coachId,input.time,input.dayIndex);return {screen:state.screen,coach:coaches[input.coachId].name,date:days[input.dayIndex].iso,time:input.time,confirmed:false}}}
 ];
